-- Pending Phase 2 foundation migration. Review before applying.
create table if not exists public.agents(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null check(length(trim(name)) between 2 and 120), instructions text not null default '', language text not null default 'en-US', voice_provider text, voice_id text, status text not null default 'draft' check(status in ('draft','active','archived')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.knowledge_sources(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null, source_type text not null check(source_type in ('file','url','text')), source_uri text, status text not null default 'pending' check(status in ('pending','ready','failed')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.contacts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, phone text, email text, consent_status text not null default 'unknown' check(consent_status in ('unknown','granted','revoked')), opted_out_at timestamptz, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, agent_id uuid references public.agents(id) on delete set null, name text not null, status text not null default 'draft' check(status in ('draft','test','paused','completed')), timezone text not null default 'UTC', start_hour smallint not null default 9 check(start_hour between 0 and 23), end_hour smallint not null default 17 check(end_hour between 1 and 24 and end_hour>start_hour), consent_required boolean not null default true, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists agents_org_idx on public.agents(organization_id);create index if not exists sources_org_idx on public.knowledge_sources(organization_id);create index if not exists contacts_org_idx on public.contacts(organization_id);create index if not exists campaigns_org_idx on public.campaigns(organization_id);
alter table public.agents enable row level security;alter table public.knowledge_sources enable row level security;alter table public.contacts enable row level security;alter table public.campaigns enable row level security;
create policy "agents_select_member" on public.agents for select using(public.is_org_member(organization_id));
create policy "agents_insert_admin" on public.agents for insert with check(exists(select 1 from public.organization_members m where m.organization_id=agents.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')) and created_by=auth.uid());
create policy "agents_update_admin" on public.agents for update using(exists(select 1 from public.organization_members m where m.organization_id=agents.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=agents.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
create policy "agents_delete_admin" on public.agents for delete using(exists(select 1 from public.organization_members m where m.organization_id=agents.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
create policy "sources_select_member" on public.knowledge_sources for select using(public.is_org_member(organization_id));create policy "sources_insert_admin" on public.knowledge_sources for insert with check(exists(select 1 from public.organization_members m where m.organization_id=knowledge_sources.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')) and created_by=auth.uid());create policy "sources_update_admin" on public.knowledge_sources for update using(exists(select 1 from public.organization_members m where m.organization_id=knowledge_sources.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=knowledge_sources.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));create policy "sources_delete_admin" on public.knowledge_sources for delete using(exists(select 1 from public.organization_members m where m.organization_id=knowledge_sources.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
create policy "contacts_select_member" on public.contacts for select using(public.is_org_member(organization_id));create policy "contacts_insert_member" on public.contacts for insert with check(public.is_org_member(organization_id));create policy "contacts_update_member" on public.contacts for update using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));create policy "contacts_delete_admin" on public.contacts for delete using(exists(select 1 from public.organization_members m where m.organization_id=contacts.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
create policy "campaigns_select_member" on public.campaigns for select using(public.is_org_member(organization_id));create policy "campaigns_insert_admin" on public.campaigns for insert with check(exists(select 1 from public.organization_members m where m.organization_id=campaigns.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')) and created_by=auth.uid());create policy "campaigns_update_admin" on public.campaigns for update using(exists(select 1 from public.organization_members m where m.organization_id=campaigns.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=campaigns.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));create policy "campaigns_delete_admin" on public.campaigns for delete using(exists(select 1 from public.organization_members m where m.organization_id=campaigns.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
